<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_login();
$config=__DIR__.'/config/database.php';if(!is_file($config)){http_response_code(503);exit('Database configuration is not ready.');}require $config;$bid=current_business_id();$notice='';$error='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf((string)($_POST['csrf']??'')))$error='Session expired. Please try again.';
 else{$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
  if($action==='deactivate'&&$id>0){$q=$pdo->prepare('SELECT COUNT(*) FROM purchases WHERE business_id=? AND supplier_id=?');$q->execute([$bid,$id]);$used=(int)$q->fetchColumn();$q=$pdo->prepare('UPDATE suppliers SET is_active=0 WHERE id=? AND business_id=?');$q->execute([$id,$bid]);$notice=$used?'Supplier is in purchase history, so it was safely made inactive.':'Supplier made inactive.';}
  else{$code=strtoupper(trim((string)($_POST['supplier_code']??'')));$name=trim((string)($_POST['supplier_name']??''));$person=trim((string)($_POST['contact_person']??''));$phone=trim((string)($_POST['phone']??''));$address=trim((string)($_POST['address']??''));$pan=trim((string)($_POST['pan_vat']??''));$remarks=trim((string)($_POST['remarks']??''));
   if($code===''||$name==='')$error='Supplier Code and Supplier Name are required.';else try{if($id>0){$q=$pdo->prepare('UPDATE suppliers SET supplier_code=?,supplier_name=?,contact_person=?,phone=?,address=?,pan_vat=?,remarks=?,is_active=1 WHERE id=? AND business_id=?');$q->execute([$code,$name,$person?:null,$phone?:null,$address?:null,$pan?:null,$remarks?:null,$id,$bid]);$notice='Supplier updated.';}else{$q=$pdo->prepare('INSERT INTO suppliers(business_id,supplier_code,supplier_name,contact_person,phone,address,pan_vat,remarks) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$bid,$code,$name,$person?:null,$phone?:null,$address?:null,$pan?:null,$remarks?:null]);$notice='Supplier saved.';}}catch(PDOException $e){$error=$e->getCode()==='23000'?'Supplier code already exists in this business.':'Supplier could not be saved.';}
  }
 }
}
if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM suppliers WHERE id=? AND business_id=?');$q->execute([(int)$_GET['edit'],$bid]);$edit=$q->fetch()?:null;}
$q=$pdo->prepare('SELECT * FROM suppliers WHERE business_id=? ORDER BY is_active DESC,supplier_name');$q->execute([$bid]);$rows=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suppliers • MeroKhata</title><link rel="stylesheet" href="assets/css/style.css"><style>.accountbar{font-size:12px;margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,.18)}.accountbar a{color:#fff}.msg{padding:10px;border-radius:8px;margin-bottom:12px}.ok{background:#ecfdf3;color:#166534}.err{background:#fff0f0;color:#991b1b}.inactive{opacity:.55}.smallbtn{display:inline-block;padding:6px 9px;border-radius:6px;text-decoration:none;border:1px solid #ccd3dd;color:#223;background:#fff;font-size:12px}.danger{color:#991b1b}</style></head><body><aside class="sidebar"><div class="brand">MeroKhata</div><div class="subbrand">Online Database</div><div class="nav"><button onclick="location.href='index.php'">Dashboard</button><button onclick="location.href='products.php'">Products</button><button class="active">Suppliers</button><button>Purchase Entry</button><button>Party / Customer</button><button>Sales & Billing</button><button>Sales Register</button><button>Sales Reports</button><button>Stock / Inventory</button><button>Price Comparison</button></div><div class="accountbar"><?=htmlspecialchars($_SESSION['name']??'User')?> · <?=htmlspecialchars(ucfirst($_SESSION['role']??''))?><br><a href="logout.php">Logout</a></div></aside><main class="main"><div class="topbar"><h1>Suppliers</h1><div class="muted">Supplier / Wholesale Shop</div></div><section class="panel active"><?php if($notice):?><div class="msg ok"><?=htmlspecialchars($notice)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=htmlspecialchars($error)?></div><?php endif;?><div class="box"><h3><?=$edit?'Edit Supplier':'Add Supplier / Wholesale Shop'?></h3><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="id" value="<?=htmlspecialchars((string)($edit['id']??0))?>"><input type="hidden" name="action" value="save"><div class="grid"><label>Supplier Code<input name="supplier_code" required value="<?=htmlspecialchars((string)($edit['supplier_code']??''))?>"></label><label>Supplier Name<input name="supplier_name" required value="<?=htmlspecialchars((string)($edit['supplier_name']??''))?>"></label><label>Contact Person<input name="contact_person" value="<?=htmlspecialchars((string)($edit['contact_person']??''))?>"></label><label>Phone<input name="phone" value="<?=htmlspecialchars((string)($edit['phone']??''))?>"></label><label>Address<input name="address" value="<?=htmlspecialchars((string)($edit['address']??''))?>"></label><label>PAN/VAT No.<input name="pan_vat" value="<?=htmlspecialchars((string)($edit['pan_vat']??''))?>"></label><label>Remarks<input name="remarks" value="<?=htmlspecialchars((string)($edit['remarks']??''))?>"></label></div><div class="actions"><button class="primary">Save Supplier</button><?php if($edit):?><button type="button" onclick="location.href='suppliers.php'">Cancel Edit</button><?php endif;?></div></form></div><div class="box"><h3>Supplier List</h3><table><thead><tr><th>Code</th><th>Supplier</th><th>Contact</th><th>Phone</th><th>Address</th><th>PAN/VAT</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $s):?><tr class="<?=$s['is_active']?'':'inactive'?>"><td><?=htmlspecialchars($s['supplier_code'])?></td><td><?=htmlspecialchars($s['supplier_name'])?><?=$s['is_active']?'':' (Inactive)'?></td><td><?=htmlspecialchars((string)$s['contact_person'])?></td><td><?=htmlspecialchars((string)$s['phone'])?></td><td><?=htmlspecialchars((string)$s['address'])?></td><td><?=htmlspecialchars((string)$s['pan_vat'])?></td><td><a class="smallbtn" href="?edit=<?=$s['id']?>">Edit</a><?php if($s['is_active']):?> <form method="post" style="display:inline" onsubmit="return confirm('Make this supplier inactive? Purchase history will remain safe.');"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="deactivate"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="smallbtn danger">Inactive</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>